sys_script.script:
(function executeRule(current, previous /*null when async*/) {
  var st = (current.application_status + "").toLowerCase();
  if (st === "approved" || st === "rejected" || st === "cancelled") return;

  var docGR = new GlideRecord("x_2200409_schola_1_scholarship_documents");
  docGR.addQuery("application", current.sys_id);
  docGR.query();
  var hasPending = false;
  var docCount = docGR.getRowCount();
  while (docGR.next()) {
    if (docGR.verification_status != "verified") {
      hasPending = true;
      break;
    }
  }

  var appUpdate = new GlideRecord("x_2200409_schola_1_scholarship_application");
  if (appUpdate.get(current.sys_id)) {
    if (docCount == 0 || hasPending) {
      if (appUpdate.application_status != "documents_pending") {
        appUpdate.application_status = "documents_pending";
        appUpdate.admin_comments = "Application set to Documents Pending: Supporting documents require verification before approval.";
        appUpdate.update();
      }
    } else {
      if (appUpdate.application_status != "under_review") {
        appUpdate.application_status = "under_review";
        appUpdate.update();
      }
      var mgr = new GlideRecord("sys_user");
      if (mgr.get("user_name", "manager.test")) {
        var apprv = new GlideRecord("sysapproval_approver");
        apprv.addQuery("source_table", "x_2200409_schola_1_scholarship_application");
        apprv.addQuery("document_id", current.sys_id);
        apprv.query();
        if (!apprv.hasNext()) {
          apprv.initialize();
          apprv.document_id = current.sys_id;
          apprv.source_table = "x_2200409_schola_1_scholarship_application";
          apprv.sysapproval = current.sys_id;
          apprv.approver = mgr.sys_id;
          apprv.state = "requested";
          var progName = current.scholarship_program.scholarship_name || current.scholarship_program.getDisplayValue();
          apprv.short_description = "Scholarship Approval: " + (current.application_number || current.number) + " - " + current.student.student_name + " (" + progName + ")";
          apprv.insert();
          gs.info("Created approval for manager.test on application " + current.application_number);
        }
      }
    }
  }
})(current, previous);
